head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// WFrame 이 읽어들인 페이지가 실제로 선언한 객체 ID.
//  scwin 과 $p 는 가이드상 항상 0번·1번 원소로 포함된다.
scwin.gVar = { declared : ["scwin", "$p", "group1", "input1", "button1"] };

scwin.btn_getObjList_onclick = function (e) {
    var objTarget = $p.getComponentById("target1");
    var arrList = objTarget.getObjList();

    var arrExtra = [];
    for (var i = 0; i < arrList.length; i++) {
        var bFound = false;
        for (var k = 0; k < scwin.gVar.declared.length; k++) {
            if (arrList[i] === scwin.gVar.declared[k]) { bFound = true; }
        }
        if (!bFound) { arrExtra.push(arrList[i]); }
    }

    scwin.setReturnValue("=====getObjList() 반환 결과=====");
    scwin.setReturnValue("    반환 목록 : " + arrList.join(", "));
    scwin.setReturnValue("    페이지가 선언한 ID : " + scwin.gVar.declared.join(", "));
    scwin.setReturnValue("    선언하지 않은 ID : " + (arrExtra.length === 0 ? "없음" : arrExtra.join(", ")));

    // 선언하지 않은 ID 가 무엇인지 확인한다.
    for (var j = 0; j < arrExtra.length; j++) {
        var objEtc = objTarget.getObj(arrExtra[j]);
        scwin.setReturnValue("        " + arrExtra[j] + " 의 정체 : "
            + (objEtc ? ("태그 " + objEtc._wTagName + " / 엔진이 부여한 uuid " + objEtc.uuid) : "확인 불가"));
    }

    scwin.setReturnValue("");
    scwin.setReturnValue("----- 판정 -----");
    if (arrExtra.length === 0) {
        scwin.setReturnValue("페이지에 정의된 객체의 ID 만 반환된다");
    } else {
        scwin.setReturnValue("페이지에 정의하지 않은 엔진 내부 ID 가 함께 반환된다 (" + arrExtra.length + "건)");
    }
    scwin.setReturnValue("");
};
